package com.google.gson.stream;

import com.google.gson.stream.JsonWriter;
import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class JsonWriter_value_TriageGen2Test {

    private JsonWriter jsonWriter;

    @Test
    public void testValue_NaN() throws IOException {
        StringWriter out = new StringWriter();
        jsonWriter = new JsonWriter(out);
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.NaN));
        assertEquals("Numeric values must be finite, but was NaN", e.getMessage());
    }

    @Test
    public void testValue_Infinity() throws IOException {
        StringWriter out = new StringWriter();
        jsonWriter = new JsonWriter(out);
        IllegalArgumentException e = assertThrows(IllegalArgumentException.class, () -> jsonWriter.value(Double.POSITIVE_INFINITY));
        assertEquals("Numeric values must be finite, but was Infinity", e.getMessage());
    }

    @Test
    public void testValue_Normal_Double() throws IOException {
        StringWriter out = new StringWriter();
        jsonWriter = new JsonWriter(out);
        jsonWriter.value(123.456);
        assertEquals("123.456", out.toString());
    }

    @Test
    public void testValue_Normal_Float() throws IOException {
        StringWriter out = new StringWriter();
        jsonWriter = new JsonWriter(out);
        jsonWriter.value(123.456f);
        assertEquals("123.456", out.toString());
    }

    @Test
    public void testValue_Normal_Integer() throws IOException {
        StringWriter out = new StringWriter();
        jsonWriter = new JsonWriter(out);
        jsonWriter.value(123);
        assertEquals("123", out.toString());
    }

    @Test
    public void testValue_NullWriter() {
        jsonWriter = new JsonWriter(null);
        assertThrows(NullPointerException.class, () -> jsonWriter.value(123.456));
    }

    @Test
    public void testValue_NullValue() {
        StringWriter out = new StringWriter();
        jsonWriter = new JsonWriter(out);
        assertThrows(NullPointerException.class, () -> jsonWriter.value(null));
    }

    @Test
    public void testValue_Serializing_Null() throws IOException {
        StringWriter out = new StringWriter();
        jsonWriter = new JsonWriter(out);
        jsonWriter.value(null);
        assertEquals("null", out.toString());
    }
}
